Proceso MayorDeUnaSerie
    Definir Mutable cantidad Como Entero <- 0;
    Definir Mutable valor Como Entero <- 0;
    Definir Mutable mayor Como Entero <- 0;
    Leer cantidad;
    Leer mayor;
    Para i <- 2 Hasta cantidad Con Paso 1 Hacer
        Leer valor;
        Si valor > mayor Entonces
            mayor <- valor;
        FinSi
    FinPara
    Escribir mayor;
FinProceso
